int gcd(int a, int b) {
    while(b) { int t = b; b = a%b; a = t; }
    return a;
}

typedef struct {
    int num, den;
} Frac;

int cmp(const void *a, const void *b) {
    Frac *fa = (Frac*)a, *fb = (Frac*)b;
    if(fa->num != fb->num) return fa->num - fb->num;
    return fa->den - fb->den;
}

