        scanf("%d", &paces[i]);
    }

    int track_length = s * 1000; // in meters

    int total_containers = 0;

    for (int hour = 0; hour < t; hour++) {
        double positions[n];
        for (int i = 0; i < n; i++) {
            double distance = paces[i] * (hour + 1); // distance in meters
            positions[i] = fmod(distance, track_length);
        }

        // sort positions
        qsort(positions, n, sizeof(double), cmp);

        int stations_needed = 0;
        int i = 0;
        while (i < n) {
            stations_needed++;
            double coverage_end = positions[i] + g;
            if (coverage_end >= track_length) {
                // wrap around: also covers from start
                // Remove all positions up to coverage_end - track_length
                double wrap_end = coverage_end - track_length;
                int j = i;
                while (j < n && positions[j] <= positions[i] + g) {
                    j++;
                }
                // also cover from start up to wrap_end
                int k = 0;
                while (k < n && positions[k] <= wrap_end) {
                    k++;
                }
                i = (j > k) ? j : k;
            } else {
                int j = i;
                while (j < n && positions[j] <= coverage_end) {
                    j++;
                }
                i = j;
            }
        }
        total_containers += stations_needed;
    }

    printf("%d\n", total_containers);
    return 0;
}

