public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        // Read number of members
        int n = Integer.parseInt(st.nextToken());
        // Read total time of the session in minutes
        int totalTime = Integer.parseInt(st.nextToken());

        // Read the pace (time per lap in minutes) for each member
        int[] paces = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            paces[i] = Integer.parseInt(st.nextToken());
        }

        // For each runner, calculate the times they pass the start/finish line
        // We use a sweep line approach to find the maximum number of concurrent water needs

        // Each water break event is at the start/finish line
        // A runner passes the start line at times: pace, 2*pace, 3*pace, ... up to totalTime

        List<int[]> events = new ArrayList<>();

        for (int pace : paces) {
            int currentTime = pace;
            while (currentTime <= totalTime) {
                // Event starts when runner arrives at water station
                events.add(new int[]{currentTime, 1}); // 1 = start of water break
                // Event ends right after they finish drinking (we can assume drinking takes negligible time)
                // For simplicity, we can consider the water break as instantaneous
                events.add(new int[]{currentTime + 1, -1}); // -1 = end of water break
                currentTime += pace;
            }
        }

        // Sort events by time, and for same time, process end events before start events
        // This ensures we count properly at boundaries
        events.sort((a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(a[1], b[1]);
        });

        int currentRunners = 0;
        int maxRunners = 0;

        for (int[] event : events) {
            if (event[1] == -1) {
                currentRunners--;
            } else {
                currentRunners++;
                maxRunners = Math.max(maxRunners, currentRunners);
            }
        }

        // The minimum number of containers needed is the maximum number of runners
        // that need water at the same time
        System.out.println(maxRunners);
    }
}

