/*
 Since the statement provided is incomplete, the implemented solution assumes the
 standard interpretation for this type of problem:

 - There are n runners on a circular track of length L.
 - Runner i runs at constant speed v[i].
 - The training lasts T hours.
 - Water is available at a fixed point on the track.
 - A runner needs one container each time they pass that point.
 - Water is refilled every hour, so we need the maximum number of passes in any
   one-hour interval over all runners combined.
 - Output the minimum number of containers required.

 Input format assumed:
 n L T
 v1 v2 ... vn

 If T is not an integer number of hours, the last partial hour is also considered.

 For each hour interval of length dt, runner i passes the water point
 floor((elapsed + dt) * v[i] / L) - floor(elapsed * v[i] / L) times.
 We compute the maximum over all hourly segments.

 If your original problem has a different exact input format, please provide it.
*/

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer nObj = fs.nextIntOrNull();
        if (nObj == null) return;
        int n = nObj;
        double L = fs.nextDouble();
        double T = fs.nextDouble();

        double[] v = new double[n];
        for (int i = 0; i < n; i++) v[i] = fs.nextDouble();

        int fullHours = (int)Math.floor(T);
        double rem = T - fullHours;

        long answer = 0;

        for (int h = 0; h < fullHours; h++) {
            double start = h;
            double len = 1.0;
            long need = 0;
            for (int i = 0; i < n; i++) {
                long a = (long)Math.floor((start * v[i]) / L + 1e-12);
                long b = (long)Math.floor(((start + len) * v[i]) / L + 1e-12);
                need += (b - a);
            }
            answer = Math.max(answer, need);
        }

        if (rem > 1e-12) {
            double start = fullHours;
            double len = rem;
            long need = 0;
            for (int i = 0; i < n; i++) {
                long a = (long)Math.floor((start * v[i]) / L + 1e-12);
                long b = (long)Math.floor(((start + len) * v[i]) / L + 1e-12);
                need += (b - a);
            }
            answer = Math.max(answer, need);
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntOrNull() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char)c);
                c = read();
            }
            return sb.toString();
        }
    }
